<template><section><el-alert title="商家合作复核" type="info" :closable="false" description="先核实事实并发出通知，保留7天申诉期，复核后才能执行。暂停合作30天或解除合作会停用该门店，已有订单记录保留。执行后撤销选定异常评价，并将50%处罚关联当月结算单。串通用户按四级规则复核，申诉期结束后联动执行。"/>
<div class="actions"><el-button @click="load" :loading="loading">刷新</el-button><el-button v-hasPermi="['kangaroo:mediation:edit']" type="primary" @click="create">新增复核通知</el-button></div><el-alert v-if="error" :title="error" type="error" :closable="false"/>
<el-table :data="rows" v-loading="loading"><el-table-column prop="caseId" label="编号" width="80"/><el-table-column prop="storeName" label="实际合作门店" min-width="180"/><el-table-column label="类型" min-width="150"><template #default="{row}">{{types[row.violation]}}</template></el-table-column><el-table-column label="状态" min-width="180"><template #default="{row}">{{states[row.status]}}</template></el-table-column><el-table-column prop="appealDeadline" label="申诉截止时间" width="175"/><el-table-column label="操作" width="110"><template #default="{row}"><el-button link type="primary" @click="view(row.caseId)">查看处理</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="page" :total="total" :page-size="20" layout="prev,pager,next,total" @current-change="load"/>
<el-dialog v-model="open" :title="detail?'商家合作复核记录':'新增商家复核通知'" width="min(760px,94vw)" :close-on-click-modal="false"><el-form label-position="top" @submit.prevent>
<template v-if="!detail"><el-form-item label="实际合作门店"><el-select v-model="form.storeId" filterable @change="loadReviews" placeholder="按店名搜索"><el-option v-for="s in stores" :key="s.storeId" :value="s.storeId" :label="s.storeName+' · '+s.city"/></el-select></el-form-item><el-form-item label="已核实的违规类型"><el-select v-model="form.violation"><el-option v-for="(name,key) in types" :key="key" :value="key" :label="name"/></el-select></el-form-item><el-form-item label="已核实的异常评价（必选）"><el-select v-model="form.reviewIds" multiple filterable allow-create default-first-option placeholder="选择评价；攻击同行时可填写已核实的评价编号"><el-option v-for="r in reviews" :key="r.reviewId" :value="r.reviewId" :label="'#'+r.reviewId+' · '+r.content"/></el-select></el-form-item><el-form-item label="事实说明（至少10字）"><el-input v-model="form.facts" type="textarea" :rows="4" maxlength="2000"/></el-form-item><el-form-item label="核验依据（至少10字，填写相关评价编号和材料线索）"><el-input v-model="form.basis" type="textarea" :rows="4" maxlength="2000"/></el-form-item></template>
<template v-else><h3>{{detail.storeName}} · {{states[detail.status]}}</h3><el-descriptions :column="1" border><el-descriptions-item label="事实">{{detail.facts}}</el-descriptions-item><el-descriptions-item label="依据">{{detail.basis}}</el-descriptions-item><el-descriptions-item label="商家申诉">{{detail.appeal||'尚未申诉'}}</el-descriptions-item><el-descriptions-item label="申诉截止">{{detail.appealDeadline}}（北京时间）</el-descriptions-item><el-descriptions-item v-if="detail.response" label="总部结果">{{detail.response}}</el-descriptions-item><el-descriptions-item v-if="detail.endsAt" label="合作限制至">{{detail.endsAt}}</el-descriptions-item><el-descriptions-item v-if="detail.feeState==='awaiting_settlement_basis'" label="费用处理">{{detail.feeMonth}} 服务费分成50%，待核对结算依据；尚未扣款</el-descriptions-item></el-descriptions>
<section v-if="detail.relatedReviews?.length"><h4>关联评价与用户复核</h4><p v-for="r in detail.relatedReviews" :key="r.reviewId">评价 #{{r.reviewId}} · {{r.content}}<template v-if="r.memberCaseId"><br/>用户复核 #{{r.memberCaseId}}：{{r.memberStatus}}<br/>申诉：{{r.appeal||'暂无'}}；截止：{{r.appealDeadline}}</template></p></section><p v-if="detail.settlement">{{detail.settlement.feeMonth}} 结算：应分成 {{money(detail.settlement.grossFen)}}，处罚扣除 {{money(detail.settlement.deductionFen)}}，实付 {{money(detail.settlement.netFen)}}；{{detail.settlement.status}}</p><template v-if="canEdit&&['notified','appealed'].includes(detail.status)"><el-form-item label="复核结论"><el-radio-group v-model="form.execute"><el-radio :value="false">撤销通知</el-radio><el-radio :value="true">确认事实并执行</el-radio></el-radio-group></el-form-item><el-alert v-if="form.execute" type="warning" :closable="false" :title="detail.violation==='competitor_attack'?'执行后解除本店合作并列入合作黑名单，不能从门店编辑直接恢复':'执行后暂停本店合作30天，岗位与房源停止公开展示'"/><el-checkbox v-if="form.execute&&detail.violation==='collusion'" v-model="form.relatedReviewed">已逐一核对关联用户事实与申诉，同意联动执行四级处理</el-checkbox><el-form-item label="复核说明（至少10字，回应申诉内容）"><el-input v-model="form.note" type="textarea" :rows="4" maxlength="2000"/></el-form-item></template><h4>处理记录</h4><el-timeline><el-timeline-item v-for="(l,i) in detail.logs" :key="i" :timestamp="l.createTime"><span class="note">{{l.note}}</span></el-timeline-item></el-timeline></template>
<el-alert v-if="saveError" :title="saveError" type="error" :closable="false"/></el-form><template #footer><el-button :disabled="busy" @click="open=false">关闭</el-button><el-button v-if="canEdit&&(!detail||['notified','appealed'].includes(detail.status))" type="primary" :loading="busy" @click="save">{{detail?'提交复核结果':'发送复核通知'}}</el-button></template></el-dialog></section></template>
<script setup>
import {ref} from 'vue';import request from '@/utils/request';import {checkPermi} from '@/utils/permission'
const types={positive_fraud:'组织刷好评',competitor_attack:'恶意攻击同行',collusion:'与用户串通刷评'},states={notified:'申诉期内',appealed:'待总部复核',cancelled:'已撤销',suspended:'暂停合作',blacklisted:'合作黑名单',expired:'已恢复合作',expired_review:'期限结束，待核实恢复'}
const canEdit=checkPermi(['kangaroo:mediation:edit']),rows=ref([]),reviews=ref([]),stores=ref([]),page=ref(1),total=ref(0),loading=ref(false),error=ref(''),detail=ref(null),open=ref(false),form=ref({}),busy=ref(false),saveError=ref('')
const api=(path,method='get',data)=>request({url:'/kangaroo/governance/'+path,method,...(method==='get'?{params:data}:{data})})
const money=n=>n==null?'待录入':'¥'+(Number(n)/100).toFixed(2)
async function loadReviews(){form.value.reviewIds=[];reviews.value=[];try{reviews.value=(await api('merchant-reviews','get',{storeId:form.value.storeId})).data}catch(e){saveError.value=e.message}}
async function load(){loading.value=true;error.value='';try{const r=(await api('merchant-cases','get',{pageNum:page.value})).data;rows.value=r.rows;total.value=r.total}catch(e){error.value=e.message}finally{loading.value=false}}
async function create(){saveError.value='';detail.value=null;reviews.value=[];form.value={storeId:null,reviewIds:[],violation:'positive_fraud',facts:'',basis:'',requestKey:'merchant_'+Date.now()+'_'+Math.random().toString(36).slice(2)};try{stores.value=(await api('merchant-stores')).data;open.value=true}catch(e){error.value=e.message}}
async function view(id){try{detail.value=(await api('merchant-cases/'+id)).data;form.value={execute:false,relatedReviewed:false,note:''};saveError.value='';open.value=true}catch(e){error.value=e.message}}
async function save(){if(busy.value)return;saveError.value='';if(detail.value?form.value.note.trim().length<10:!form.value.storeId||form.value.facts.trim().length<10||form.value.basis.trim().length<10){saveError.value='请选门店并完整填写至少10字的事实、依据或复核说明';return}busy.value=true;try{await api(detail.value?'merchant-cases/'+detail.value.caseId+'/decision':'merchant-cases','post',form.value);open.value=false;await load()}catch(e){saveError.value=e.message||'提交失败，内容保留，可重试'}finally{busy.value=false}}
load()
</script><style scoped>.actions{display:flex;gap:12px;margin:20px 0}.el-pagination{margin-top:20px}.el-select{width:100%}.el-alert{margin-bottom:14px}.note{white-space:pre-wrap;overflow-wrap:anywhere}</style>
